MODELS = {
    "model_a": {"reasoning": 5, "speed": 2, "cost_efficiency": 2},
    "model_b": {"reasoning": 4, "speed": 4, "cost_efficiency": 3},
    "model_c": {"reasoning": 3, "speed": 5, "cost_efficiency": 5},
}

WEIGHTS = {"reasoning": 0.5, "speed": 0.2, "cost_efficiency": 0.3}

def weighted_score(caps, weights):
    return round(sum(caps[axis] * weights[axis] for axis in weights), 1)

scores = {name: weighted_score(caps, WEIGHTS) for name, caps in MODELS.items()}
ranking = sorted(scores.items(), key=lambda kv: kv[1], reverse=True)
for name, score in ranking:
    print(f"{name}: {score}")
print(f"winner={ranking[0][0]}")
